H.background();
const Qh = Math.max(Math.abs(P.Qh), 1);
const Qc = Math.min(Math.abs(P.Qc), Qh);
const W = Qh - Qc;
const e = 1 - Qc / Qh;
H.text("Heat-engine efficiency: e = 1 - Qc/Qh = W/Qh", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("A cyclic engine takes in Qh, dumps Qc, does work W = Qh - Qc", 24, 52, { color: H.colors.sub, size: 13 });
const cx = 450, cy = 300, R = 70;
const ph = (t * 0.8) % H.TAU;
const eng = Math.abs(Math.sin(ph));
H.rect(cx - R, cy - R, 2 * R, 2 * R, { fill: H.colors.panel, stroke: H.colors.axis, width: 2, radius: 10 });
H.text("ENGINE", cx, cy - 8, { color: H.colors.ink, size: 14, align: "center", weight: 700 });
H.text("W = " + W.toFixed(0) + " J", cx, cy + 14, { color: H.colors.good, size: 13, align: "center" });
const hotY = 110, coldY = 490;
H.rect(cx - 120, hotY - 22, 240, 30, { fill: "#3a1f1f", stroke: H.colors.warn, width: 2, radius: 6 });
H.text("HOT reservoir Th", cx, hotY - 4, { color: H.colors.warn, size: 13, align: "center", weight: 700 });
H.rect(cx - 120, coldY - 8, 240, 30, { fill: "#1f2c3a", stroke: H.colors.accent, width: 2, radius: 6 });
H.text("COLD reservoir Tc", cx, coldY + 14, { color: H.colors.accent, size: 13, align: "center", weight: 700 });
// Qh in (animated flow downward)
const fy1 = hotY + 8 + ((t * 60) % (cy - R - hotY - 8));
H.arrow(cx, hotY + 8, cx, cy - R, { color: H.colors.warn, width: 3 });
H.circle(cx, fy1, 5, { fill: H.colors.warn });
H.text("Qh = " + Qh.toFixed(0) + " J", cx - 150, (hotY + cy) / 2, { color: H.colors.warn, size: 13, align: "right" });
// Qc out
const fy2 = cy + R + ((t * 60) % (coldY - 8 - cy - R));
H.arrow(cx, cy + R, cx, coldY - 8, { color: H.colors.accent, width: 3 });
H.circle(cx, fy2, 5, { fill: H.colors.accent });
H.text("Qc = " + Qc.toFixed(0) + " J", cx + 150, (coldY + cy) / 2, { color: H.colors.accent, size: 13, align: "left" });
// W out arrow to side
const wx = cx + R + 6 + eng * 40;
H.arrow(cx + R, cy, cx + R + 90, cy, { color: H.colors.good, width: 3 });
H.circle(wx, cy, 5, { fill: H.colors.good });
// efficiency bar
const bx = 80, by = 470, bw = 200, bh = 22;
H.rect(bx, by, bw, bh, { stroke: H.colors.axis, width: 1, radius: 4 });
H.rect(bx, by, bw * e, bh, { fill: H.colors.good, radius: 4 });
H.text("e = " + (100 * e).toFixed(1) + " %", bx, by - 8, { color: H.colors.good, size: 14, weight: 700 });
